{
  "cases": [
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"alpha\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 5}, {\"op\": \"reserve\", \"tenant\": \"beta\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 5}]",
      "family": "tenant_isolation",
      "name": "same key different tenants stock isolation"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"gamma\", \"key\": \"k2\", \"sku\": \"sensor\", \"qty\": 3}, {\"op\": \"stock\", \"tenant\": \"gamma\", \"sku\": \"widget\"}, {\"op\": \"stock\", \"tenant\": \"gamma\", \"sku\": \"sensor\"}]",
      "family": "tenant_isolation",
      "name": "cross sku stock visibility"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"delta\", \"key\": \"k3\", \"sku\": \"widget\", \"qty\": 10}, {\"op\": \"reserve\", \"tenant\": \"delta\", \"key\": \"k3\", \"sku\": \"widget\", \"qty\": 10}, {\"op\": \"release\", \"tenant\": \"delta\", \"key\": \"k3\"}, {\"op\": \"reserve\", \"tenant\": \"delta\", \"key\": \"k3\", \"sku\": \"widget\", \"qty\": 10}]",
      "family": "idempotency",
      "name": "post-release idempotent retry"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"epsilon\", \"key\": \"k4\", \"sku\": \"widget\", \"qty\": 1}, {\"op\": \"reserve\", \"tenant\": \"epsilon\", \"key\": \"k4\", \"sku\": \"widget\", \"qty\": 1}, {\"op\": \"release\", \"tenant\": \"epsilon\", \"key\": \"k4\"}, {\"op\": \"release\", \"tenant\": \"epsilon\", \"key\": \"k4\"}]",
      "family": "idempotency",
      "name": "double release no double restore"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"zeta\", \"key\": \"k5\", \"sku\": \"widget\", \"qty\": 2}, {\"op\": \"reserve\", \"tenant\": \"zeta\", \"key\": \"k5\", \"sku\": \"sensor\", \"qty\": 2}]",
      "family": "payload_binding",
      "name": "key reuse with different sku conflict"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"eta\", \"key\": \"k6\", \"sku\": \"widget\", \"qty\": 2}, {\"op\": \"reserve\", \"tenant\": \"eta\", \"key\": \"k6\", \"sku\": \"widget\", \"qty\": 3}]",
      "family": "payload_binding",
      "name": "key reuse with different qty conflict"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"theta\", \"key\": \"k7\", \"sku\": \"widget\", \"qty\": 0}]",
      "family": "validation",
      "name": "zero quantity invalid"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"iota\", \"key\": \"k8\", \"sku\": \"widget\", \"qty\": 1.5}]",
      "family": "validation",
      "name": "float quantity invalid"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"kappa\", \"key\": \"k9\", \"sku\": \"widget\", \"qty\": 11}]",
      "family": "validation",
      "name": "quantity over max invalid"
    },
    {
      "actions_json": "[{\"op\": \"release\", \"tenant\": \"lambda\", \"key\": \"k10\"}]",
      "family": "inventory",
      "name": "release without reservation not found"
    }
  ]
,
  "rationale": "The observed counterexamples reveal critical failures in tenant isolation (stock leakage across tenants), idempotency (retries consuming stock), payload binding (conflicts ignored), and validation (negative/invalid types accepted). The new test suite addresses these by: 1) Verifying strict tenant isolation for stock counts and reservation keys; 2) Testing idempotency after releases to ensure no double-restoration or double-consumption; 3) Enforcing payload binding conflicts when SKU or Qty changes under the same key; 4) Validating boundary conditions for quantity (0, float, >10); 5) Ensuring release errors on non-existent reservations do not affect state."
}
